$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.IO.Compression
$dialog = New-Object System.Windows.Forms.OpenFileDialog
$dialog.Title = 'Close the counter, then select maple_loot_counter.py'
$dialog.Filter = 'Counter source|maple_loot_counter.py'
if ($dialog.ShowDialog() -ne 'OK') { return }
$folder = Split-Path -Parent $dialog.FileName
$backup = Join-Path $folder ('auto_update_backup_' + (Get-Date -Format 'yyyyMMdd_HHmmss_fff'))
$staged = @()
$changed = @()
$archive = $null
try {
    $old = [IO.File]::ReadAllText($dialog.FileName)
    if (-not $old.Contains('class MapleLootCounter(') -or -not $old.Contains('install_all_items_ui')) {
        throw 'Unexpected program version. No files changed.'
    }
    $payload = [Convert]::FromBase64String('')
    $stream = New-Object IO.MemoryStream(,$payload)
    $archive = New-Object IO.Compression.ZipArchive($stream, [IO.Compression.ZipArchiveMode]::Read)
    $allowed = @('skill_worker.py', 'instance_lock.py', 'settings_store.py', 'recognition_state.py', 'daily_records.py', 'verified_items.json', 'recognition_trace.py', 'first_run.py', 'quickslot_picker.py', 'chat_tracker.py', 'ocr_engine.py', 'quickslot_auto.py', 'skill_timers.py', 'chat_windows.py', 'tracking_profiles.py', 'maple_loot_counter.py', 'all_items_ui.py', 'assets/chat_tabs_embedded.png', 'hunting_meso.py', 'goal_ui.py', 'hunting_api.py', 'api_key_store.py', 'hunting_buffs.py', 'buff_wealth.png', 'buff_union_wealth.png', 'buff_union_luck.png', 'build_exe.py', 'window_controls.py', 'global_hotkey.py', 'app_updater.py', 'updater_ui.py', 'AUTO_UPDATE_README.txt')
    if ($archive.Entries.Count -ne 32) { throw 'Invalid patch contents.' }
    foreach ($entry in $archive.Entries) {
        if ($entry.FullName -notin $allowed) { throw 'Invalid patch filename.' }
        $target = Join-Path $folder $entry.FullName
        [IO.Directory]::CreateDirectory((Split-Path -Parent $target)) | Out-Null
        $temp = $target + '.stage_' + [Guid]::NewGuid().ToString('N')
        $source = $entry.Open()
        $dest = [IO.File]::Create($temp)
        try { $source.CopyTo($dest) } finally { $dest.Dispose(); $source.Dispose() }
        $staged += [pscustomobject]@{ Target=$target; Temp=$temp; Name=$entry.FullName; Existed=(Test-Path -LiteralPath $target) }
    }
    $python = Join-Path $folder '.venv_ocr\Scripts\python.exe'
    if (Test-Path -LiteralPath $python) {
        $paths = @($staged | Where-Object { $_.Name.EndsWith('.py') } | ForEach-Object { $_.Temp })
        & $python -c 'import ast,sys,pathlib; [ast.parse(pathlib.Path(p).read_bytes()) for p in sys.argv[1:]]' @paths
        if ($LASTEXITCODE -ne 0) { throw 'Code validation failed. No files changed.' }
    }
    New-Item -ItemType Directory -Path $backup | Out-Null
    foreach ($item in $staged) {
        if ($item.Existed) {
            $backupFile = Join-Path $backup $item.Name
            [IO.Directory]::CreateDirectory((Split-Path -Parent $backupFile)) | Out-Null
            Copy-Item -LiteralPath $item.Target -Destination $backupFile
        }
    }
    foreach ($item in $staged) {
        $changed += $item
        [IO.File]::Copy($item.Temp, $item.Target, $true)
    }
    [System.Windows.Forms.MessageBox]::Show('Patch complete. Start run.bat and use the Update button. Read AUTO_UPDATE_README.txt. Existing EXE files must be rebuilt.', 'Auto update setup') | Out-Null
} catch {
    $problem = $_.Exception.Message
    foreach ($item in $changed) {
        if ($item.Existed) {
            Copy-Item -LiteralPath (Join-Path $backup $item.Name) -Destination $item.Target -Force
        } elseif (Test-Path -LiteralPath $item.Target) {
            Remove-Item -LiteralPath $item.Target
        }
    }
    [System.Windows.Forms.MessageBox]::Show($problem, 'Auto update setup failed') | Out-Null
    throw
} finally {
    foreach ($item in $staged) {
        if (Test-Path -LiteralPath $item.Temp) { Remove-Item -LiteralPath $item.Temp }
    }
    if ($archive) { $archive.Dispose() }
    $dialog.Dispose()
}
